<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import type { CartaFianza,CartaFianzaFiltros,CartaFianzaPayload,CartaFianzaResponse,OpcionCartaFianza } from '../interfaces/carta-fianza.interface'
import { activarCartaFianza,guardarCartaFianza,listarCartasFianza,obtenerCartaFianza } from '../services/carta-fianza'
const blankFilters=():CartaFianzaFiltros=>({texto:'',tipo_carta_fianza_id:'',banco_id:'',moneda_id:'',sentido:'',estado:'',fecha_desde:'',fecha_hasta:'',por_vencer:false})
const blankForm=():CartaFianzaPayload=>({numero:'',sentido:'EMITIDA',tipo_carta_fianza_id:0,banco_id:0,moneda_id:0,monto:0,fecha_emision:'',fecha_inicio:'',fecha_vencimiento:'',ordenante_tipo_documento:'RUC',ordenante_numero_documento:'',ordenante_nombre:'',beneficiario_tipo_documento:'RUC',beneficiario_numero_documento:'',beneficiario_nombre:'',objeto_garantia:'',dias_alerta:30,tasa_comision:0,importe_comision:0,numero_contrato:'',numero_expediente:'',numero_proceso:'',observaciones:''})
const filters=reactive(blankFilters()),form=reactive(blankForm()),rows=ref<CartaFianza[]>([]),tipos=ref<OpcionCartaFianza[]>([]),bancos=ref<OpcionCartaFianza[]>([]),monedas=ref<OpcionCartaFianza[]>([]),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),error=ref(''),success=ref(''),editing=ref<number|null>(null),showForm=ref(false),detail=ref<CartaFianza|null>(null)
const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.',money=(v:number,m?:OpcionCartaFianza)=>new Intl.NumberFormat('es-PE',{style:'currency',currency:m?.codigo||'PEN'}).format(Number(v||0)),date=(v?:string)=>v?new Date(`${v}T00:00:00`).toLocaleDateString('es-PE'):'-'
function consume(r:CartaFianzaResponse){rows.value=r.data;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total;tipos.value=r.tipos_carta_fianza||[];bancos.value=r.bancos||[];monedas.value=r.monedas||[]}
async function load(next=1){loading.value=true;error.value='';try{consume(await listarCartasFianza(filters,next))}catch(e){error.value=message(e)}finally{loading.value=false}}
function create(){editing.value=null;Object.assign(form,blankForm());showForm.value=true}
async function edit(item:CartaFianza){loading.value=true;try{const data=await obtenerCartaFianza(item.id);editing.value=item.id;Object.assign(form,blankForm(),data);showForm.value=true}catch(e){error.value=message(e)}finally{loading.value=false}}
async function view(item:CartaFianza){loading.value=true;try{detail.value=await obtenerCartaFianza(item.id)}catch(e){error.value=message(e)}finally{loading.value=false}}
async function save(){loading.value=true;error.value='';try{await guardarCartaFianza(editing.value,{...form});success.value=`Carta fianza ${editing.value?'actualizada':'registrada'} correctamente.`;showForm.value=false;await load(page.value)}catch(e){error.value=message(e)}finally{loading.value=false}}
async function activate(item:CartaFianza){if(!confirm(`¿Activar la carta fianza ${item.numero}?`))return;loading.value=true;try{await activarCartaFianza(item.id);success.value='Carta fianza activada.';await load(page.value)}catch(e){error.value=message(e)}finally{loading.value=false}}
function clear(){Object.assign(filters,blankFilters());load(1)}
const tone=(v:string)=>['VIGENTE'].includes(v)?'good':['ANULADA','EJECUTADA','VENCIDA'].includes(v)?'bad':'warn'
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Finanzas / Cartas Fianza</nav><header class="hero"><div><small>MIA · FINANZAS · GARANTÍAS</small><h1>Cartas Fianza</h1><p>Registro, seguimiento y control de garantías emitidas y recibidas.</p></div><strong>{{total}} registros</strong><button @click="create">+ Nueva carta fianza</button></header><p v-if="error" class="flash badmsg">{{error}}</p><p v-if="success" class="flash okmsg">{{success}}</p><form class="filters" @submit.prevent="load(1)"><input v-model.trim="filters.texto" class="wide" placeholder="Número, ordenante, beneficiario, contrato o expediente"><select v-model="filters.tipo_carta_fianza_id"><option value="">Todos los tipos</option><option v-for="x in tipos" :key="x.id" :value="x.id">{{x.nombre}}</option></select><select v-model="filters.banco_id"><option value="">Todos los bancos</option><option v-for="x in bancos" :key="x.id" :value="x.id">{{x.nombre}}</option></select><select v-model="filters.moneda_id"><option value="">Todas las monedas</option><option v-for="x in monedas" :key="x.id" :value="x.id">{{x.nombre}}</option></select><select v-model="filters.sentido"><option value="">Todo sentido</option><option>EMITIDA</option><option>RECIBIDA</option></select><select v-model="filters.estado"><option value="">Todo estado</option><option v-for="x in ['BORRADOR','VIGENTE','VENCIDA','EJECUTADA','LIBERADA','ANULADA']" :key="x">{{x}}</option></select><input v-model="filters.fecha_desde" type="date"><input v-model="filters.fecha_hasta" type="date"><label><input v-model="filters.por_vencer" type="checkbox"> Por vencer</label><div><button>Filtrar</button><button type="button" class="soft" @click="clear">Limpiar</button></div></form><section class="card"><div v-if="loading" class="empty">Procesando…</div><div v-else-if="!rows.length" class="empty">No se encontraron cartas fianza.</div><div v-else class="scroll"><table><thead><tr><th>Número / tipo</th><th>Banco</th><th>Intervinientes</th><th>Monto</th><th>Vigencia</th><th>Sentido</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td><b>{{item.numero}}</b><small>{{item.tipo_carta_fianza?.nombre}}</small></td><td>{{item.banco?.nombre}}</td><td><b>{{item.ordenante_nombre}}</b><small>Beneficiario: {{item.beneficiario_nombre}}</small></td><td><b>{{money(item.monto,item.moneda)}}</b><small>{{item.moneda?.nombre}}</small></td><td>{{date(item.fecha_inicio)}}<small>hasta {{date(item.fecha_vencimiento)}}</small></td><td>{{item.sentido}}</td><td><span :class="tone(item.estado)">{{item.estado}}</span></td><td class="actions"><button @click="view(item)">Ver</button><button v-if="item.estado==='BORRADOR'" class="soft" @click="edit(item)">Editar</button><button v-if="item.estado==='BORRADOR'" class="activate" @click="activate(item)">Activar</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section>
<div v-if="showForm" class="backdrop" @mousedown.self="showForm=false"><form class="dialog" @submit.prevent="save"><header><div><small>{{editing?'EDICIÓN':'NUEVO REGISTRO'}}</small><h2>{{editing?'Editar':'Registrar'}} carta fianza</h2></div><button type="button" @click="showForm=false">×</button></header><div class="grid"><label>Número<input v-model="form.numero" required></label><label>Sentido<select v-model="form.sentido" required><option>EMITIDA</option><option>RECIBIDA</option></select></label><label>Tipo<select v-model.number="form.tipo_carta_fianza_id" required><option :value="0">Seleccione</option><option v-for="x in tipos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Banco<select v-model.number="form.banco_id" required><option :value="0">Seleccione</option><option v-for="x in bancos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Moneda<select v-model.number="form.moneda_id" required><option :value="0">Seleccione</option><option v-for="x in monedas" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Monto<input v-model.number="form.monto" type="number" min="0.01" step="0.01" required></label><label>Emisión<input v-model="form.fecha_emision" type="date" required></label><label>Inicio<input v-model="form.fecha_inicio" type="date" required></label><label>Vencimiento<input v-model="form.fecha_vencimiento" type="date" required></label><label>Días de alerta<input v-model.number="form.dias_alerta" type="number" min="0"></label><label class="span2">Ordenante<input v-model="form.ordenante_nombre" required></label><label class="span2">Beneficiario<input v-model="form.beneficiario_nombre" required></label><label class="span2">Objeto de la garantía<textarea v-model="form.objeto_garantia" required></textarea></label><label>Contrato<input v-model="form.numero_contrato"></label><label>Expediente<input v-model="form.numero_expediente"></label><label class="span2">Observaciones<textarea v-model="form.observaciones"></textarea></label></div><footer><button type="button" class="soft" @click="showForm=false">Cancelar</button><button :disabled="loading">Guardar</button></footer></form></div>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="dialog detail"><header><div><small>CARTA FIANZA #{{detail.id}}</small><h2>{{detail.numero}}</h2></div><span :class="tone(detail.estado)">{{detail.estado}}</span><button @click="detail=null">×</button></header><div class="facts"><div><small>TIPO / SENTIDO</small><b>{{detail.tipo_carta_fianza?.nombre}} · {{detail.sentido}}</b></div><div><small>BANCO</small><b>{{detail.banco?.nombre}}</b></div><div><small>MONTO</small><b>{{money(detail.monto,detail.moneda)}}</b></div><div><small>VENCIMIENTO</small><b>{{date(detail.fecha_vencimiento)}}</b></div></div><h3>Intervinientes</h3><p><b>Ordenante:</b> {{detail.ordenante_nombre}}<br><b>Beneficiario:</b> {{detail.beneficiario_nombre}}</p><h3>Objeto de garantía</h3><p>{{detail.objeto_garantia}}</p><h3>Documentos ({{detail.documentos?.length||0}})</h3><ul><li v-for="x in detail.documentos" :key="x.id">{{x.nombre_original||x.nombre}} · {{x.tipo}}</li></ul><h3>Historial</h3><ul><li v-for="x in detail.historial" :key="x.id"><b>{{x.accion}}</b> — {{x.descripcion}}</li></ul></section></div></div></template>
<style scoped>
.page{--a:#176d78;color:#344750}nav{margin-bottom:15px;color:#91a0a5;font-size:.68rem}nav a{color:var(--a)}.hero{display:flex;align-items:center;gap:15px;padding:20px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.hero>div{flex:1}.hero small,.dialog small{color:var(--a);font-size:.5rem;font-weight:800}.hero h1{margin:3px 0;font-size:1.35rem}.hero p{margin:0;color:#79898f;font-size:.65rem}.hero strong{font-size:.55rem}button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.5rem;cursor:pointer}.soft{color:#607078;background:#edf2f3}.activate{background:#26875e}.flash{padding:10px;border-radius:6px;font-size:.55rem}.badmsg{color:#9b3d48;background:#fdebee}.okmsg{color:#236c50;background:#e8f7ee}.filters{margin-top:11px;padding:12px;display:grid;grid-template-columns:2fr repeat(5,1fr) 125px 125px auto auto;gap:7px;background:#fff}.filters input,.filters select,.grid input,.grid select,.grid textarea{min-width:0;box-sizing:border-box;padding:8px;border:1px solid #d4dde0;border-radius:5px;background:#fff;font-size:.5rem}.filters label{display:flex;align-items:center;gap:4px;font-size:.5rem}.filters>div,.actions{display:flex;gap:5px}.card{margin-top:11px;background:#fff}.scroll{overflow:auto}table{width:100%;min-width:1100px;border-collapse:collapse;font-size:.5rem}th,td{padding:9px;border-bottom:1px solid #e4eaec;text-align:left;vertical-align:top}th{color:#fff;background:#435d6c}td small{display:block;margin-top:3px;color:#829096}.good,.bad,.warn{display:inline-block;padding:4px 7px;border-radius:10px;font-size:.48rem;font-weight:800}.good{color:#247052;background:#e4f6eb}.bad{color:#9c424a;background:#fdebed}.warn{color:#896013;background:#fff3d7}.empty{padding:45px;text-align:center}.card>footer,.dialog>footer{padding:11px;display:flex;justify-content:center;align-items:center;gap:8px}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(850px,100%);max-height:92vh;padding:20px;box-sizing:border-box;border-radius:12px;background:#fff;overflow:auto}.dialog>header{display:flex;align-items:flex-start;gap:10px}.dialog>header div{flex:1}.dialog h2{margin:3px 0 15px}.dialog>header button{color:#66757b;background:none;font-size:1.2rem}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.grid label{display:grid;gap:4px;color:#62737a;font-size:.5rem;font-weight:700}.grid textarea{min-height:65px;resize:vertical}.span2{grid-column:span 2}.facts{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.facts div{display:grid;gap:4px;padding:10px;background:#f2f6f7}.detail h3{margin:18px 0 7px;font-size:.7rem}.detail p,.detail li{font-size:.55rem}.detail ul{padding-left:18px}@media(max-width:1100px){.filters{grid-template-columns:repeat(4,1fr)}.wide{grid-column:span 2}}@media(max-width:650px){.filters,.grid,.facts{grid-template-columns:1fr}.wide,.span2{grid-column:auto}.hero{align-items:flex-start;flex-wrap:wrap}}
</style>
